def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    rich_pressure = 0
    desperate_opp = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if bid >= 120:
                    rich_pressure += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_opp += 1

    if budget <= 0:
        return 0.0

    player_count = 1 + len(alive)
    enough_for_all = supply >= WATER_REQ * player_count
    very_tight = supply < WATER_REQ * max(1, player_count - 1)

    highest_prev = max(prev_bids) if prev_bids else 0.0

    if hp <= 2 or no_water >= 2:
        bid = max(0.92 * DAILY_SALARY, highest_prev + 2.0)
    elif hp <= 4 or no_water >= 1:
        bid = max(0.78 * DAILY_SALARY, min(highest_prev + 1.0, 0.98 * DAILY_SALARY))
    elif very_tight:
        bid = max(0.82 * DAILY_SALARY, min(highest_prev + 1.5, DAILY_SALARY * 1.02))
    elif enough_for_all:
        bid = 0.22 * DAILY_SALARY
    else:
        if rich_pressure >= 2:
            bid = 0.34 * DAILY_SALARY
        elif desperate_opp >= 2:
            bid = 0.62 * DAILY_SALARY
        else:
            bid = max(0.45 * DAILY_SALARY, min(highest_prev * 0.55, 0.68 * DAILY_SALARY))

    day_num = day_context['day']
    if day_num >= 8 and hp >= 6 and budget < DAILY_SALARY * 2:
        bid *= 0.85

    if budget < bid:
        bid = budget
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    yesterday_bids = []
    yesterday_hp_after = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace') or {}
        if prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass
        try:
            if prev.get('hp_after') is not None:
                yesterday_hp_after.append(int(prev.get('hp_after')))
        except Exception:
            pass

    # Base target: around typical yesterday bids, but avoid overpaying.
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        mean_prev = sum(yesterday_bids) / float(len(yesterday_bids))
    else:
        max_prev = 0.0
        mean_prev = DAILY_SALARY * 0.6

    # Supply pressure: when supply is tight, increase bid.
    # Convert supply to an approximate scarcity factor.
    scarcity = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = (float(MAX_SUPPLY) - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    # If I'm low hp or have been without water, bid more.
    low_hp = 1 if my_hp <= 2 else 0
    moderate_hp = 1 if my_hp == 3 else 0
    urgency = 0.0
    if my_no_water_days >= 2:
        urgency = 0.25
    if my_no_water_days >= 3:
        urgency = 0.45

    # Decide cap and aggressiveness based on yesterday's max.
    # If others were extremely aggressive, we slightly overbid; otherwise we undercut/meet.
    if max_prev >= DAILY_SALARY * 1.45:
        aggressiveness = 0.18
    elif max_prev >= DAILY_SALARY * 1.25:
        aggressiveness = 0.10
    else:
        aggressiveness = 0.06

    # Target bid formula.
    target = mean_prev * (1.0 + aggressiveness) + (DAILY_SALARY * 0.15) * scarcity

    # Raise for low hp / urgency.
    if low_hp:
        target = max(target, DAILY_SALARY * 0.9)
    elif moderate_hp:
        target = max(target, DAILY_SALARY * 0.7)

    if urgency > 0.0:
        target = target * (1.0 + urgency)

    # Ensure we don't exceed a reasonable fraction of budget.
    # If budget is very low, spend enough to avoid immediate death but not all.
    if my_budget <= DAILY_SALARY * 0.6:
        cap_frac = 0.85
    elif my_budget <= DAILY_SALARY * 1.2:
        cap_frac = 0.65
    else:
        cap_frac = 0.55

    bid = min(my_budget * cap_frac, target)

    # Safety floor: avoid bidding too tiny when supply is scarce.
    min_bid = DAILY_SALARY * (0.35 + 0.25 * scarcity)
    bid = max(bid, min_bid if my_hp > 0 else 0.0)

    # Final clamp to non-negative.
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive = len(alive_opponents) + 1

    # Calculate a competitive bid based on supply scarcity
    # If supply is tight, bid higher to ensure survival
    if supply < (num_alive * WATER_REQ * 0.8):
        base_bid = DAILY_SALARY * 1.3
    else:
        base_bid = DAILY_SALARY * 0.9

    # Adjust for low HP
    if my_status['hp'] < 4:
        base_bid = DAILY_SALARY * 1.5

    # Look at yesterday's max bid to stay competitive
    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if 'previous_trace' in o and o['previous_trace'].get('bid')]
    if prev_bids:
        max_prev = max(prev_bids)
        bid = max(base_bid, max_prev + 2.0)
    else:
        bid = base_bid

    return float(min(my_status['budget'], bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Gather yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_yesterday = max(yesterday_bids)
    else:
        max_yesterday = 0

    # Base margin over yesterday's max
    margin = 2.0

    # Urgency based on current hp
    if my_hp <= 2 or my_no_water > 0:
        # Desperate: bid high up to 0.9 salary
        target = min(my_budget, DAILY_SALARY * 0.9)
    elif my_hp <= 4:
        # Moderate urgency
        if max_yesterday > DAILY_SALARY * 0.8:
            target = min(my_budget, max_yesterday + margin)
        else:
            target = min(my_budget, DAILY_SALARY * 0.7)
    else:
        # Healthy: conserve budget
        if max_yesterday > DAILY_SALARY * 0.8:
            target = min(my_budget, DAILY_SALARY * 0.45)
        else:
            target = min(my_budget, max_yesterday + margin, DAILY_SALARY * 0.65)

    # Ensure non-negative and at least a minimal bid (0.1 salary) if we have budget
    bid = max(0.0, target)
    if my_budget < bid:
        bid = my_budget * 0.9  # fallback if budget too low
    # Ensure we don't bid more than we have
    bid = min(bid, my_budget)
    # Keep bid reasonable but not zero unless truly broke
    if bid < 1.0 and my_budget >= 1.0:
        bid = 1.0
    return bid
